#!/usr/bin/env node
/**
 * Writes content/wikiqorgi/catalog.ts: every wikiqorgi article's slug,
 * headline, Wikipedia source title, dek and section — everything except the
 * body.
 *
 * Why a generated file: the dynamic routes (/wiki/[slug], /search) and the
 * edge proxy need to know what is on the shelf, but importing
 * content/wikiqorgi would pull ~2 MB of article HTML into each of their
 * bundles. The catalog is the few kilobytes they actually use.
 *
 * content/wikiqorgi/index.ts compares this file with the real articles at
 * import time and fails the build if they differ, so forgetting to rerun this
 * after adding or editing an article is caught, not shipped.
 *
 * Usage: npm run gen:catalog
 *
 * Reads the article modules as text rather than importing them: they are
 * TypeScript with path aliases, and every field needed here is a one-line
 * string literal (asserted below).
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const shelfDir = join(root, "content", "wikiqorgi");
const index = readFileSync(join(shelfDir, "index.ts"), "utf8");

// import { blackHole } from "./black-hole";  ->  blackHole => black-hole.ts
const fileByIdentifier = new Map(
  [...index.matchAll(/^import \{ (\w+) \} from "\.\/([\w-]+)";$/gm)].map((m) => [m[1], m[2]]),
);

function field(source, name, file) {
  const match = new RegExp(`^  ${name}: ("(?:[^"\\\\]|\\\\.)*"),$`, "m").exec(source);
  if (!match) throw new Error(`${file}: no one-line string literal for "${name}"`);
  return JSON.parse(match[1]);
}

const sectionsBlock = index.slice(index.indexOf("export const WIKIQORGI_SECTIONS"));
const sectionRe = /id: "([^"]+)",\s*title: "([^"]+)",[\s\S]*?articles: \[([^\]]*)\]/g;

const catalog = [];
for (const [, , sectionTitle, list] of sectionsBlock.matchAll(sectionRe)) {
  for (const identifier of list.split(",").map((s) => s.trim()).filter(Boolean)) {
    const file = fileByIdentifier.get(identifier);
    if (!file) throw new Error(`index.ts: no import found for ${identifier}`);
    const source = readFileSync(join(shelfDir, `${file}.ts`), "utf8");
    catalog.push({
      slug: field(source, "slug", file),
      title: field(source, "title", file),
      sourceTitle: field(source, "sourceTitle", file),
      dek: field(source, "dek", file),
      section: sectionTitle,
    });
  }
}

if (catalog.length === 0) throw new Error("No articles found — has index.ts changed shape?");

const body = catalog.map((entry) => `  ${JSON.stringify(entry)},`).join("\n");
writeFileSync(
  join(shelfDir, "catalog.ts"),
  `// Generated by scripts/generate-wikiqorgi-catalog.mjs — do not edit by hand.
// Run \`npm run gen:catalog\` after adding or editing an article.
import type { ShelfEntry } from "@/lib/shelf-search";

export const WIKIQORGI_CATALOG: ShelfEntry[] = [
${body}
];
`,
);

console.log(`Wrote ${catalog.length} entries to content/wikiqorgi/catalog.ts`);
